save(393,dict(paragraphs=["Sankha Ranjan Patra is a poet and fiction writer from West Bengal whose writing spans English, Bengali and Hindi. His English poetry collections include Muse and Mute; his other books include All About Love and the Bengali poetry collection Borsha. Publisher and journal biographies place poetry at the centre of a practice that also extends into fiction and anthology contributions.","‘Let It Happen’ gives emotional absence the scale of a cosmic event. Repeated invitations to let the world collapse lead through rocks, oceans and empty space to the possibility of a loved one returning as a comet. The final question leaves a small opening for reunion within the poem’s language of destruction."],sources=[source('Notion Press — Mute',u,'Search-index book page includes exact author, West Bengal, English/Bengali, Muse and Mute; ISBN9781684944309. Direct open redirect loop.','search_index'),source('Setu — Sankha Ranjan Patra','https://www.setumag.com/2025/06/special-edition-sankha-ranjan-patra.html','Search-index full contributor biography matches captured languages and four titles/genres. Direct open cache miss.','search_index'),source('Clever Fox Publishing storefront — Muse','https://www.mystore.in/en/product/muse-paperback-sankha-ranjan-patra','Publisher seller, exact author/title, poetry, ISBN9788194681861. Direct open cache miss.','search_index')],books=[dict(title='Muse',detail='English poetry. Clever Fox Publishing. ISBN 9788194681861.',url='https://www.mystore.in/en/product/muse-paperback-sankha-ranjan-patra'),dict(title='Mute',detail='English poetry. Notion Press. ISBN 9781684944309.',url=u)],identity_match='Exact full name and overlapping Muse/Mute bibliography bridge publisher biography to captured profile; Setu confirms all four titles and languages.',poems_read=[dict(id=541,title='Let It Happen',coverage='Full eighteen-line original.',basis='Repeated collapse, ocean/vacancy, absence and comet return.')],limitations=['All external sources accessed through search index; direct opens failed as recorded.','Older publisher biography lists two languages; later Setu and captured biography list three. No chronology of language acquisition inferred.','Specific honours not identified; no award names or dates added.','Book descriptions read, not full books; no claim of close reading those books.'],research_leads=[],next_action='Independent editorial review, direct-link recheck and confirmation of any named honours.'))
